-- v4.4.10 additive role-template repair; migration 55 remains checksum-stable.
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'wallboard' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY)
WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY,ENABLED) VALUES (s.CAPABILITY_KEY,'N','Y');
DECLARE c NUMBER; BEGIN SELECT COUNT(*) INTO c FROM USER_TAB_COLUMNS WHERE TABLE_NAME='CX_MODEL_ROUTING_POLICIES' AND COLUMN_NAME='GATEWAY_URL'; IF c=0 THEN EXECUTE IMMEDIATE 'ALTER TABLE CX_MODEL_ROUTING_POLICIES ADD (GATEWAY_URL VARCHAR2(512))'; END IF; END;
DECLARE c NUMBER; BEGIN SELECT COUNT(*) INTO c FROM USER_INDEXES WHERE INDEX_NAME='IDX_MODEL_ROUTE_SCOPE_UQ'; IF c=0 THEN EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX IDX_MODEL_ROUTE_SCOPE_UQ ON CX_MODEL_ROUTING_POLICIES (NVL(AGENT_ID,''#''),NVL(PROFILE_ID,''#''))'; END IF; END;
UPDATE CX_ROLE_TEMPLATES SET PERMISSIONS_JSON='["audit.read","audit.export","users.read","profile.update","organizations.read","organizations.history.read","organizations.export","wallboard.read","model_usage.read"]' WHERE ROLE_CODE='AUDITOR';
